pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betLimit, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(betLimit) {} catch { return; }
        uint256 before = address(c).balance;
        try c.wager{value: amount}() {} catch { return; }
        uint256 afterB = address(c).balance;
        bool wagered;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wagered = __r; } catch { return; }
        assertTrue(afterB == before + amount && wagered == (amount == betLimit && amount > 0));
    }

    function testFuzz_run(uint256 betLimit, uint256 amount) public {
        _run(betLimit, amount);
    }

    receive() external payable {}
}
